import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Simple Calculator',      home: Calculator(),    );  }}class Calculator extends StatefulWidget {  const Calculator({Key? key}) : super(key: key);  @override  State<Calculator> createState() => _CalculatorState();}class _CalculatorState extends State<Calculator> {  final _controller = TextEditingController();  double _num1 = 0;  double _num2 = 0;  String _operator = '';  String _result = '';  void _calculate() {    setState(() {      switch (_operator) {        case '+':          _result = (_num1 + _num2).toString();          break;        case '-':          _result = (_num1 - _num2).toString();          break;        case '*':          _result = (_num1 * _num2).toString();          break;        case '/':          if (_num2 != 0) {            _result = (_num1 / _num2).toString();          } else {            _result = 'Error';          }          break;      }    });  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Simple Calculator'),      ),      body: Padding(        padding: const EdgeInsets.all(16.0),        child: Column(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            TextField(              controller: _controller,              decoration: const InputDecoration(                border: OutlineInputBorder(),                labelText: 'Enter numbers and operator (e.g., 2+2)',              ),              onChanged: (text) {                setState(() {                  final parts = text.split(RegExp(r'[+*/-]'));                  if (parts.length == 2) {                    _num1 = double.parse(parts[0]);                    _num2 = double.parse(parts[1]);                    _operator = text.substring(parts[0].length, text.length - parts[1].length);                  }                });              },            ),            ElevatedButton(              onPressed: _calculate,              child: const Text('Calculate'),            ),            Text(              _result.isEmpty ? 'Result: ' : 'Result: $_result',              style: const TextStyle(fontSize: 24),            ),          ],        ),      ),    );  }}